  private async applySearch(): Promise<void> {
    const trimmed = this.currentQuery.trim();
    if (trimmed === '') {
      // Restore drill view at CURRENT drillPath (D-12) — NOT rootPath.
      await this.renderDrillView();
      return;
    }
    await this.renderSearchResults(trimmed);
